{
  "title": "Scholarship Applications Overview",
  "subtitle": "Summary of scholarship applications across sites and categories",
  "panels": [
    {
      "id": "p1",
      "kind": "kpi",
      "title": "Total applications",
      "sql": "SELECT COUNT(*) AS n FROM \"scholarship_applicants\"",
      "unit": ""
    },
    {
      "id": "p2",
      "kind": "bar",
      "title": "Applications by site",
      "sql": "SELECT \"School\" AS site, COUNT(*) AS n FROM \"scholarship_applicants\" GROUP BY 1 ORDER BY 2 DESC LIMIT 10",
      "x": "site",
      "y": ["n"]
    },
    {
      "id": "p3",
      "kind": "line",
      "title": "Monthly trend",
      "sql": "SELECT \"DOB\" AS month, COUNT(*) AS total FROM \"scholarship_applicants\" GROUP BY 1 ORDER BY 1",
      "x": "month",
      "y": ["total"]
    },
    {
      "id": "p4",
      "kind": "table",
      "title": "Top 10 categories",
      "sql": "SELECT \"Category\", COUNT(*) AS n FROM \"scholarship_applicants\" GROUP BY 1 ORDER BY 2 DESC LIMIT 10"
    }
  ],
  "narrative": "The dashboard shows the total number of scholarship applications received, broken down by school and tracked over time. It also highlights the most common categories among applicants. These insights help the board monitor application volumes and identify key areas for outreach."
}

