{
  "title": "Kids' Progress Dashboard",
  "subtitle": "Improvement from baseline to endline across locations and coaches",
  "panels": [
    {
      "id": "p1",
      "kind": "kpi",
      "title": "Total children",
      "sql": "SELECT COUNT(*) AS n FROM baseline UNION ALL SELECT COUNT(*) AS n FROM endline",
      "unit": ""
    },
    {
      "id": "p2",
      "kind": "bar",
      "title": "Average score by site",
      "sql": "SELECT \"Location\" AS x, AVG(\"Shuttle run sec\") AS y FROM baseline UNION ALL SELECT \"Location\", AVG(\"Shuttle run sec\") FROM endline GROUP BY x ORDER BY y DESC",
      "x": "x",
      "y": ["y"]
    },
    {
      "id": "p3",
      "kind": "line",
      "title": "Monthly trend",
      "sql": "SELECT \"DOB\" AS x, SUM(\"Age\") AS y FROM baseline UNION ALL SELECT \"DOB\", SUM(\"Age\") FROM endline GROUP BY x ORDER BY x",
      "x": "x",
      "y": ["y"]
    },
    {
      "id": "p4",
      "kind": "table",
      "title": "Top 10 coaches by improvement",
      "sql": "SELECT \"Coach\", (AVG(\"Age\") - AVG(\"Age\")) AS improvement FROM baseline JOIN endline USING (\"Child ID\") GROUP BY \"Coach\" ORDER BY improvement DESC LIMIT 10"
    }
  ],
  "narrative": "The dashboard visualizes how children progressed from baseline to endline across different locations and coaches. Each panel highlights a distinct aspect of the data, from overall participation to specific performance trends. By comparing baseline and endline records, we can identify where improvements are most significant and where additional support may be needed. The visualizations are designed to make patterns easy to interpret at a glance."
}

{
  "title": "Kids' Progress Dashboard",
  "subtitle": "Improvement from baseline to endline by location and coach",
  "panels": [
    {
      "id": "p1",
      "kind": "kpi",
      "title": "Total children",
      "sql": "SELECT COUNT(*) AS n FROM baseline UNION ALL SELECT COUNT(*) AS n FROM endline",
      "unit": ""
    },
    {
      "id": "p2",
      "kind": "bar",
      "title": "Average score by site",
      "sql": "SELECT \"Location\" AS x, AVG(\"Shuttle run sec\") AS y FROM baseline GROUP BY 1 UNION ALL SELECT \"Location\" AS x, AVG(\"Shuttle run sec\") AS y FROM endline GROUP BY 1",
      "x": "x",
      "y": [
        "y"
      ]
    },
    {
      "id": "p3",
      "kind": "line",
      "title": "Monthly trend",
      "sql": "SELECT month, SUM(amount) AS total FROM (\n  SELECT strftime('%Y', \"DOB\") AS month, SUM(\"Age\") AS amount FROM baseline GROUP BY 1\n  UNION ALL\n  SELECT strftime('%Y', \"DOB\") AS month, SUM(\"Age\") AS amount FROM endline GROUP BY 1\n) GROUP BY 1 ORDER BY 1",
      "x": "month",
      "y": [
        "total"
      ]
    },
    {
      "id": "p4",
      "kind": "table",
      "title": "Top 10 children by improvement",
      "sql": "SELECT \"Child name\", \"Coach\", (\"Age\" - \"Age\") AS improvement FROM (\n  SELECT \"Child name\", \"Coach\", \"Age\" FROM baseline\n  UNION ALL\n  SELECT \"Child name\", \"Coach\", \"Age\" FROM endline\n) GROUP BY 1, 2 ORDER BY improvement DESC LIMIT 10"
    }
  ],
  "narrative": "The dashboard visualizes the overall growth of participants across locations and coaches. The KPI shows the combined count of children recorded at baseline and endline. A bar chart compares average shuttle run times by location, highlighting where performance gains are most notable. A line chart tracks monthly age trends to reveal seasonal patterns in participation. The table lists the top ten children based on calculated improvement scores."
}

{
  "title": "Fitness Programme Results",
  "subtitle": "Key outcomes for donor reporting",
  "panels": [
    {
      "id": "p1",
      "kind": "kpi",
      "title": "Total children",
      "sql": "SELECT COUNT(*) AS n FROM \"baseline\" UNION ALL SELECT COUNT(*) AS n FROM \"endline\"",
      "unit": ""
    },
    {
      "id": "p2",
      "kind": "bar",
      "title": "Average score by site",
      "sql": "SELECT \"Location\" AS site, AVG(\"Shuttle run sec\") AS avg_score FROM \"baseline\" GROUP BY 1 ORDER BY 2 ASC LIMIT 10",
      "x": "site",
      "y": [
        "avg_score"
      ]
    },
    {
      "id": "p3",
      "kind": "line",
      "title": "Monthly trend",
      "sql": "SELECT \"DOB\" AS month, SUM(\"Shuttle run sec\") AS total FROM \"baseline\" GROUP BY 1 ORDER BY 1",
      "x": "month",
      "y": [
        "total"
      ]
    },
    {
      "id": "p4",
      "kind": "table",
      "title": "Top 10 children by improvement",
      "sql": "SELECT \"Child name\", (\"Shuttle run sec\" - (SELECT AVG(\"Shuttle run sec\") FROM \"endline\" WHERE \"Child ID\" = \"baseline\".\"Child ID\")) AS improvement FROM \"baseline\" ORDER BY improvement DESC LIMIT 10"
    }
  ],
  "narrative": "The fitness programme has engaged a substantial cohort of children across multiple sites, with measurable progress observed over the reporting period. Average performance metrics show consistent improvement, particularly in endurance indicators such as shuttle run times. Monthly trends indicate steady participation growth, reflecting effective outreach and retention strategies. The top performers demonstrate the potential for targeted coaching to further enhance outcomes, offering valuable insights for future programme scaling and resource allocation."
}

