{
  "title": "School Dashboard",
  "subtitle": "Enrolment trends, infrastructure gaps, and gender comparison",
  "panels": [
    {
      "id": "p1",
      "kind": "kpi",
      "title": "Total students",
      "sql": "SELECT SUM(\"Girls 2022\" + \"Girls 2023\" + \"Girls 2024\" + \"Boys 2022\" + \"Boys 2023\" + \"Boys 2024\") AS n FROM \"school_enrolment_by_year\"",
      "unit": ""
    },
    {
      "id": "p2",
      "kind": "line",
      "title": "Monthly trend",
      "sql": "SELECT \"Survey Round\" AS month, SUM(\"Households surveyed\") AS total FROM \"district_health_factsheet\" GROUP BY 1 ORDER BY 1",
      "x": "month",
      "y": ["total"]
    },
    {
      "id": "p3",
      "kind": "bar",
      "title": "Average score by site",
      "sql": "SELECT \"School Name\" AS site, AVG(\"Girls 2022\" + \"Girls 2023\" + \"Girls 2024\" + \"Boys 2022\" + \"Boys 2023\" + \"Boys 2024\") / 6 AS avg_score FROM \"school_enrolment_by_year\" GROUP BY 1 ORDER BY 2 DESC LIMIT 10",
      "x": "site",
      "y": ["avg_score"]
    },
    {
      "id": "p4",
      "kind": "table",
      "title": "Top 10 schools by total enrolment",
      "sql": "SELECT \"School Name\", (\"Girls 2022\" + \"Girls 2023\" + \"Girls 2024\" + \"Boys 2022\" + \"Boys 2023\" + \"Boys 2024\") AS total FROM \"school_enrolment_by_year\" ORDER BY total DESC LIMIT 10"
    }
  ],
  "narrative": "The dashboard shows the overall student count across all schools, highlighting the scale of enrolment. A line chart tracks the monthly surveyed households to illustrate data collection activity over time. Bar visualisation ranks schools by their average enrolment, giving a quick view of the most active institutions. Finally, a table lists the top ten schools by total student numbers, providing a concise reference for resource allocation."
}

